def median(nums: list) -> float:
    """Return the median of a non‑empty list of numbers.
    For odd length, return the middle element.
    For even length, return the mean of the two middle elements.
    The result is always a float.
    """
    if not nums:
        raise ValueError("median requires a non-empty list")
    # ensure numeric types; Python will raise TypeError on invalid comparisons
    sorted_nums = sorted(nums)
    n = len(sorted_nums)
    mid = n // 2
    if n % 2:
        return float(sorted_nums[mid])
    else:
        return float((sorted_nums[mid - 1] + sorted_nums[mid]) / 2)

def merge_intervals(iv: list) -> list:
    """Merge overlapping [start, end] intervals; return them sorted by start. Touching intervals merge."""
    if not iv:
        return []
    # Ensure each interval is a list or tuple of two numbers
    intervals = sorted(iv, key=lambda x: x[0])
    merged = [intervals[0]]
    for current in intervals[1:]:
        last = merged[-1]
        # If current starts before or exactly at last end, merge
        if current[0] <= last[1]:
            merged[-1] = [last[0], max(last[1], current[1])]
        else:
            merged.append(current)
    return merged

def valid_parens(s: str) -> bool:
    """Return True if every (, [, { is closed by the matching bracket in the right order."""
    stack: list[str] = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

import csv
from pathlib import Path

_cache = None


def _load_rates():
    global _cache
    if _cache is not None:
        return _cache
    data_file = Path('data') / 'ecb_rates_2019.csv'
    if not data_file.exists():
        raise FileNotFoundError(f"{data_file} not found")
    rates = {}
    with data_file.open(newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            date = row.get('Date') or row.get('date')
            rate = row.get('EUR') or row.get('Rate')
            if date is not None and rate is not None:
                try:
                    rates[date] = float(rate)
                except ValueError:
                    pass
    _cache = rates
    return rates

def fx_rate(date: str) -> float:
    """Return the USD->EUR closing rate on the given date, read from data/ecb_rates_2019.csv."""
    rates = _load_rates()
    if date not in rates:
        raise KeyError(f"Rate for {date} not found")
    return rates[date]

